(function () {
  'use strict';
  const chunkSet = {"title":"Text Evidence","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-text-evidence-q0051","version":3,"contentHash":"sha256:45f44fd5fdc9d40c16615a19a25ccb24f661574a55df1ba7b4cee0823ce66b13","question":"Read the passage. Grade 3 foundation passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The title names the topic but gives no proof.","The school choir rehearsed a song about the moon.","The passage says every reader already knew about bike safety.","She showed how helmets should sit flat and snug on a rider's head."],"correct":3,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly explains or supports your main point or answer.","example":"Point: Dogs need exercise. Evidence: 'The active dog ran three miles with his owner every single morning.'","strategyClue":"Look for the sentence in the text that specifically describes the physical position or condition of the helmet mentioned in your answer choice.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence directly describes how a helmet should fit on the head to provide safety, which supports the claim about correct fit.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The passage does not have a title, and mentioning a title does not provide evidence about how a helmet should physically fit."},{"choice":"The school choir rehearsed a song about the moon.","category":"unrelated content","reason":"This information is completely unrelated to bike safety or helmet use, making it impossible to use as evidence for this topic."},{"choice":"The passage says every reader already knew about bike safety.","category":"false information","reason":"The passage never states that readers already knew about bike safety; it provides instructions instead."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":51,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0052","version":3,"contentHash":"sha256:8fe0a3afde76a915f6356c4d9320824da96bdf9406fb4316c145f42fb7a4caf7","question":"Read the passage. Grade 3 foundation passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The new route stopped near the clinic, grocery store, and community center.","A bakery sold cinnamon rolls before sunrise.","The passage says every reader already knew about city buses.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"A supporting sentence provides evidence, facts, or details that prove the main idea is true.","example":"Main Idea: The park is fun. Supporting Detail: It has a tall slide and a swing set.","strategyClue":"Look for a sentence in the passage that links the 'new route' to places people actually use in their daily lives.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides specific locations that directly show how the route supports the community's daily needs.","incorrect":["",{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence is not found in the passage and does not relate to bus routes or serving community needs."},{"choice":"The passage says every reader already knew about city buses.","category":"unsupported claim","reason":"The passage does not mention what readers know; it describes the actions taken by transportation planners."},{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This sentence is not part of the text and does not provide evidence from the passage regarding the bus route's purpose."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":52,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0053","version":3,"contentHash":"sha256:c6e12d740e33a4a729c2aea3e5bb2ab88f062319f74c62b1eba1a9ba3cb34986","question":"Read the passage. Grade 3 foundation passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The passage says every reader already knew about school play.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports your answer to a question.","example":"Question: How was the weather bad? Text: 'The wind howled and trees bent to the ground.' Evidence: 'The wind howled and trees bent to the ground.'","strategyClue":"Search the text for nouns or verbs that describe people working behind the scenes. If a detail describes someone doing a task other than speaking or acting, it supports the idea that the production involves more than just acting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly mentions the work of the stage crew (painting and testing lights), which proves that the play involved many tasks beyond just the actors performing.","incorrect":[{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This detail describes a math poster, which has nothing to do with the work or the production of a stage play."},"",{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"The passage does not mention what the readers know; this statement is not supported by any evidence in the provided text."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title is just a label for the story. It does not provide the specific actions or examples needed to support the claim about what the production required."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":53,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0054","version":3,"contentHash":"sha256:2cdcf091caf0a212462b11b1482f9f899b69bd3eb96bb3e74d71d2633cfa99a5","question":"Read the passage. Grade 3 foundation passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["The passage says every reader already knew about compost bin.","A new scoreboard was installed in the gym.","After several weeks, the dark compost was mixed into flower beds.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support an idea, look for a sentence that proves the claim is true by showing the specific result or action described in the idea.","example":"Claim: Recycling saves space. Supporting sentence: The city reduced its trash by recycling thousands of bottles.","strategyClue":"Look at the key words in the idea ('food scraps', 'useful', 'not thrown away'). Find the sentence that explicitly describes what happened to the scraps after they were collected.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence provides evidence that the food scraps were successfully used for a purpose (nourishing flowers) rather than being sent to a landfill.","incorrect":[{"choice":"The passage says every reader already knew about compost bin.","category":"Unsupported claim","reason":"The passage does not mention what the reader knows. This statement is not found in the text and does not show how food scraps become useful."},{"choice":"A new scoreboard was installed in the gym.","category":"Irrelevant information","reason":"This sentence describes an event in the gym, but it has no connection to food scraps or composting."},"",{"choice":"The title names the topic but gives no proof.","category":"Misinterpretation of text","reason":"This comment describes a title, but it does not provide evidence from the text to show that food scraps were reused."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":54,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0055","version":3,"contentHash":"sha256:d6daa213145169f296f1ad74f15528df3e2ba9cc921de3d79adf65b87fcd01b2","question":"Read the passage. Grade 3 foundation passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The title names the topic but gives no proof.","The music teacher tuned a violin before class.","The passage says every reader already knew about weather station.","They measured rainfall, wind direction, temperature, and cloud cover every day."],"correct":3,"studyAid":{"definition":"To support a statement with evidence, look for specific details or examples in the text that directly relate to the point being made.","example":"Claim: 'The character is busy.' Evidence: 'She checked her watch, ran to the bus, and missed her lunch.'","strategyClue":"Identify the key nouns in the claim being tested, then scan the passage for sentences that list multiple items or actions matching those categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data collection, proving that the students gathered more than one kind of weather evidence.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"Titles often introduce a topic, but they do not provide specific data or evidence about what actions the characters took."},{"choice":"The music teacher tuned a violin before class.","category":"off-topic choice","reason":"This sentence describes music class, which is not mentioned in the passage about science and weather tracking."},{"choice":"The passage says every reader already knew about weather station.","category":"misreading the text","reason":"The passage does not mention what readers already knew; it only describes the specific observations made by the students."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":55,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0056","version":3,"contentHash":"sha256:95365f1cf921fba0c0362852789274f15effd70ffc4270456853da8d82961f1e","question":"Read the passage. Grade 3 foundation passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["By winter break, the school ordered fewer boxes of printer paper.","The nurse checked the first-aid supplies after lunch.","The passage says every reader already knew about recycling team.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, find a sentence that provides specific evidence, data, or a direct result that matches the claim being made.","example":"Claim: The garden grew well. Evidence: We harvested ten baskets of vegetables by August.","strategyClue":"Identify the key action or change mentioned in the claim (like 'how much paper was used'), then look for the sentence that shows the actual result of that change.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides evidence that the school's paper consumption decreased, which confirms that the plan successfully changed the amount of paper used.","incorrect":["",{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence mentions school supplies, but it has nothing to do with recycling or the amount of printer paper being used."},{"choice":"The passage says every reader already knew about recycling team.","category":"unsupported claim","reason":"This statement is not found in the text provided, and it does not offer any evidence regarding the school's paper usage."},{"choice":"The title names the topic but gives no proof.","category":"non-evidence statement","reason":"While a title might name a topic, a title is not a sentence from the passage that proves the change in paper usage."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":56,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0057","version":3,"contentHash":"sha256:29a6e05aad2de27fce9faf117f01bb744a32762f77ef337f459adb8f4c106cbe","question":"Read the passage. Grade 3 foundation passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["A rainstorm delayed the baseball game.","Visitors could press buttons to hear recordings of elders telling memories.","The passage says every reader already knew about museum exhibit.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for a claim, look for specific details in the text that directly support or explain that exact idea.","example":"Claim: 'The pet store had many animals.' Evidence: 'The shop was filled with barking dogs, chirping birds, and swimming fish.'","strategyClue":"Break your target sentence into parts (like 'objects' and 'stories'). Search the text for a specific word or phrase that matches each part of your claim.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides direct evidence of personal stories, while the tools, photographs, letters, and map provide evidence of objects.","incorrect":[{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This information is not found in the passage and has nothing to do with the museum exhibit's contents."},"",{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The passage never mentions what the readers knew; it focuses specifically on what was inside the exhibit."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"A title might introduce a topic, but you must find specific sentences within the body of the text that prove a claim is true."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":57,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0058","version":3,"contentHash":"sha256:3cd6d5a0d6bde8684122ccaabee1bd935cd7d5ad40e2d7bd97cfd3f018d25e43","question":"Read the passage. Grade 3 foundation passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The passage says every reader already knew about robotics club.","The principal announced picture day over the speaker.","Each time the robot missed a turn, members adjusted the code and tested again.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence consists of specific details, facts, or actions from the text that prove a main idea is true.","example":"Main Idea: 'My dog is helpful.' Supporting detail: 'He carries the mail to my door every afternoon.'","strategyClue":"Look for the specific action in the text that demonstrates the club turning a negative event (a failure) into a positive improvement.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the club learning from a 'missed turn' (a mistake) by adjusting their approach, which directly supports the idea that they treated errors as information.","incorrect":[{"choice":"The passage says every reader already knew about robotics club.","category":"not in text","reason":"This information is not present in the provided passage and does not relate to the club's process of learning from mistakes."},{"choice":"The principal announced picture day over the speaker.","category":"unrelated topic","reason":"This sentence is about a school announcement and contains no details about the robot or the club's problem-solving process."},"",{"choice":"The title names the topic but gives no proof.","category":"unsupported claim","reason":"This does not provide evidence for the idea of using mistakes; it talks about a title, which is not referenced in the text provided."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":58,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0059","version":3,"contentHash":"sha256:131e1bd8097d6bb98fe3d172131e4c23f4fac2dfdd78f7e998fb236df2565e44","question":"Read the passage. Grade 3 foundation passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The title names the topic but gives no proof.","The science lab received new magnifying glasses.","The passage says every reader already knew about school breakfast.","Students who arrived close to the bell could still choose a quick meal."],"correct":3,"studyAid":{"definition":"To find the strongest evidence, identify the sentence that directly answers the 'why' or 'how' part of the question.","example":"Question: Why is the plant dying? Evidence: The soil is completely dry because it hasn't rained in weeks.","strategyClue":"Look at the question to see what specific problem it asks about (in this case, 'little time'), then scan the text for words related to 'time' or 'speed'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This sentence directly describes students having a limited amount of time before class starts and explains how the cart accommodates them.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"This is a statement about a title, which is not mentioned in the passage and does not provide evidence about the breakfast cart's purpose."},{"choice":"The science lab received new magnifying glasses.","category":"unrelated content","reason":"This sentence mentions a science lab and tools, which has nothing to do with the breakfast cart or the time students have before class."},{"choice":"The passage says every reader already knew about school breakfast.","category":"unsupported claim","reason":"This statement is not supported by the text and does not explain how the cart helps students who are in a hurry."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":59,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0060","version":3,"contentHash":"sha256:2bfed1bbda48b2d60f032a1cf98530c84da8bb3181fb74b275b3f7de19f94df2","question":"Read the passage. Grade 3 foundation passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["They added arrows, distance signs, and small plaques naming common trees.","The post office closed early on Saturday.","The passage says every reader already knew about nature trail.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, you must find evidence in the text that directly matches the specific details mentioned in the idea.","example":"Idea: The kitchen is messy. Evidence: The sink is full of dirty dishes and crumbs cover the floor.","strategyClue":"Break the idea into two parts: 'directions' and 'information.' Look for the specific words in the passage that represent those two categories.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence explicitly mentions 'arrows' and 'distance signs' for directions, and 'plaques naming common trees' for information.","incorrect":["",{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence does not appear in the passage and has nothing to do with hiking trails, signs, or information for visitors."},{"choice":"The passage says every reader already knew about nature trail.","category":"unsupported claim","reason":"The passage never mentions what the readers already knew, making this sentence an incorrect interpretation of the text."},{"choice":"The title names the topic but gives no proof.","category":"incorrect summary","reason":"This is a comment about the passage structure rather than evidence from the text that proves the signs provide directions and information."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":60,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0061","version":3,"contentHash":"sha256:c62e6771cd0852665318598c86a77e706895648399d33bc19820e6d53a7caab9","question":"Read the passage. Grade 3 developing passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. These details show that students used careful daily routines to help a garden grow.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The art room displayed clay bowls near the window.","They recorded how tall the seedlings grew.","The passage says every reader already knew about school garden.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence is a sentence from the text that directly proves or explains the main idea or a claim.","example":"Claim: 'The dog was tired.' Supporting Evidence: 'The dog napped for three hours on the rug.'","strategyClue":"Highlight the key words in the claim (like 'observations' and 'care for the plants'), then scan the text for a sentence that describes an action matching those specific words.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence directly describes students gathering specific data through observation to monitor plant development.","incorrect":[{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"This sentence describes art supplies, not the garden or the students' work with plants, making it unrelated to the main idea."},"",{"choice":"The passage says every reader already knew about school garden.","category":"factual inaccuracy","reason":"The passage never states that the reader already knew about the garden; this choice does not provide evidence from the text."},{"choice":"The title names the topic but gives no proof.","category":"not textual evidence","reason":"The title might introduce the subject, but it does not describe an action taken by the students to care for the plants through observation."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":61,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0062","version":3,"contentHash":"sha256:b45cef9bb7866426bdb203af254170dd44401e0ff470763997ba5e05f386cb6a","question":"Read the passage. Grade 3 developing passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. These details show that student volunteers organized books and labels to make the library easier to use.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The passage says every reader already knew about library helpers.","The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports your claim or answer.","example":"Claim: 'The character is kind.' Evidence: 'She shared her last cookie with her friend.'","strategyClue":"Ask yourself: 'Which sentence describes a specific action that makes finding a book faster?' Ignore sentences about other topics or ideas not found in the text.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains how books are organized so readers can locate specific materials quickly using the call number system.","incorrect":[{"choice":"The passage says every reader already knew about library helpers.","category":"not in text","reason":"This information is not mentioned in the passage, so it cannot serve as evidence for how volunteers helped readers."},{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This detail describes a cafeteria event that has nothing to do with the library or how volunteers organized books."},"",{"choice":"The title names the topic but gives no proof.","category":"incorrect evidence type","reason":"While a title might give a clue about the topic, it does not provide the specific actions taken by volunteers to improve library efficiency."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":62,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0063","version":3,"contentHash":"sha256:5ffae401c0c81b827ed1cda6ee013210e82a96e8862d42202067c93d8652f13a","question":"Read the passage. Grade 3 developing passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. These details show that a science club collected and reused rainwater to care for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["The title names the topic but gives no proof.","A soccer team practiced corner kicks after school.","The passage says every reader already knew about rain barrel.","Members used the stored water on dry afternoons instead of turning on the hose."],"correct":3,"studyAid":{"definition":"To find a sentence that supports an idea, look for text that describes the specific action or event proving that idea is true.","example":"Claim: I like fruit. Evidence: I ate an apple for lunch today.","strategyClue":"Identify the key words in the claim—in this case, 'rain barrel,' 'reduced,' and 'hose.' Scan the passage for the sentence that explains the relationship between the barrel and the hose usage.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly connects the act of using collected rainwater to the reduction of using the hose, which is the definition of reducing the need for hose water.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"Titles often describe the main idea, but they do not contain the specific evidence or actions needed to prove how a system works."},{"choice":"A soccer team practiced corner kicks after school.","category":"off-topic sentence","reason":"This sentence is about soccer, not science or rainwater. It does not provide any evidence related to the rain barrel project."},{"choice":"The passage says every reader already knew about rain barrel.","category":"unsupported claim","reason":"The passage never mentions what the reader knows or doesn't know; always look for evidence actually written in the text."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":63,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0064","version":3,"contentHash":"sha256:de8e72626fbca233ab8c46bc0d011a46f72a2d65759ffa1aa182b24a5aed8452","question":"Read the passage. Grade 3 developing passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. These details show that student reporters gathered facts and published school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["They interviewed teachers, wrote short articles, and checked facts before printing.","The playground slide was painted blue over spring break.","The passage says every reader already knew about class newspaper.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support an idea, you must choose evidence from the text that directly explains or proves that specific point.","example":"If the claim is 'The dog was hungry,' the evidence is 'The dog ate his food quickly,' not 'The dog is brown.'","strategyClue":"Look for the specific action in the text that matches the goal mentioned in the question (in this case, 'accuracy'). Ask yourself which choice shows the reporters doing work to make sure their information was correct.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. Checking facts is the direct action that proves a reporter is trying to be accurate and truthful in their writing.","incorrect":["",{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant information","reason":"This fact describes the school's physical environment, not the actions of the reporters or the quality of their newspaper."},{"choice":"The passage says every reader already knew about class newspaper.","category":"unsupported claim","reason":"The passage never mentions what the readers knew; therefore, this cannot serve as evidence for the reporters' actions."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title might introduce a topic, but it does not provide the specific evidence needed to show the effort made toward accuracy."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":64,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0065","version":3,"contentHash":"sha256:63d27e8b52ac7a4b7464c3c1e741b985986bcdfb53680ab4fe3bf115095988d2","question":"Read the passage. Grade 3 developing passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. These details show that families cleaned litter from the beach and encouraged visitors to keep it clean.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The town band played a concert in the park.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The passage says every reader already knew about beach cleanup.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To support a claim, you must find a specific detail in the text that directly proves the idea is true.","example":"Claim: The garden is messy. Support: There are weeds growing over the flowers and fallen leaves everywhere.","strategyClue":"Look for a sentence that lists specific examples of the materials removed from the beach, as these are the physical items that would pose a danger to animals.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides specific evidence of the action taken (removing dangerous debris) that directly supports the claim that the beach became safer for wildlife.","incorrect":[{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence describes a completely different event and does not mention litter, beach cleanup, or wildlife safety."},"",{"choice":"The passage says every reader already knew about beach cleanup.","category":"not in text","reason":"This statement is not a sentence from the passage and makes an assumption about the reader that is not supported by the text."},{"choice":"The title names the topic but gives no proof.","category":"metatextual commentary","reason":"This is a comment about the structure of the passage rather than a piece of evidence that supports the claim about wildlife safety."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":65,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0066","version":3,"contentHash":"sha256:1e1c11d35a9252e13e65b62be7801d4c9ce88c4127d7176c1a73190b3da9a573","question":"Read the passage. Grade 3 developing passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. These details show that a safety officer taught students important bike safety habits.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The passage says every reader already knew about bike safety.","The school choir rehearsed a song about the moon.","She showed how helmets should sit flat and snug on a rider's head.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Evidence is a fact or specific detail from the text that proves an idea or a claim is true.","example":"Claim: The classroom was messy. Evidence: Papers were scattered across the floor and desks were pushed out of place.","strategyClue":"Look for a sentence that talks about the same subject as your claim. If your claim is about a helmet's fit, identify the specific sentence in the passage that explains what a helmet's fit should actually look like.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence specifically describes the physical requirement for wearing a helmet, which directly supports the claim about how it must fit to provide protection.","incorrect":[{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The passage never mentions what the readers already know. Information must be found directly in the text to serve as evidence."},{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This detail is completely unrelated to the topic of bike safety or helmets, so it cannot be used as evidence."},"",{"choice":"The title names the topic but gives no proof.","category":"missing evidentiary support","reason":"While titles can provide context, they are not detailed sentences that prove a specific claim about how a helmet should fit."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":66,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0067","version":3,"contentHash":"sha256:2f7182b7157ee0da2b6c63ef9bb52ecace483bcc6a9dd13d8b33694d2b38382f","question":"Read the passage. Grade 3 developing passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. These details show that transportation planners improved bus service so people could reach useful places.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The title names the topic but gives no proof.","A bakery sold cinnamon rolls before sunrise.","The passage says every reader already knew about city buses.","The new route stopped near the clinic, grocery store, and community center."],"correct":3,"studyAid":{"definition":"To support a main idea, choose a sentence from the text that provides specific examples, facts, or evidence related to that idea.","example":"Main Idea: 'Plants need water.' Supporting sentence: 'Without regular watering, the leaves turned brown and dry.'","strategyClue":"Look for the sentence that acts as proof by naming specific places, people, or actions that directly relate to the key words in the prompt's main idea.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides specific evidence of 'community needs' by listing important locations people rely on, such as a health facility and food source.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not a sentence","reason":"This is a statement about the text rather than a quote from the passage itself, and it does not provide any evidence that the bus route met community needs."},{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence is not found in the passage and has nothing to do with transportation planning or the bus routes mentioned in the text."},{"choice":"The passage says every reader already knew about city buses.","category":"incorrect text evidence","reason":"This statement is not supported by the passage, and it fails to identify any specific stops or services that would prove the bus route served the community."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":67,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0068","version":3,"contentHash":"sha256:5fd1ae7f6916204ce23acd554387020555ad589d8bf97aeded53633d02ea425d","question":"Read the passage. Grade 3 developing passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. These details show that actors and crew members cooperated to get a play ready.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["Actors practiced lines while stage crew members painted scenery and tested lights.","A math poster showed different kinds of triangles.","The passage says every reader already knew about school play.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence consists of specific facts or details from the text that directly prove or explain the main point or question.","example":"Question: How was the storm dangerous? Evidence: The high winds knocked over large trees and tore shingles off the roof.","strategyClue":"Identify the key terms in the question, such as 'production' and 'more than acting,' then scan the text for sentences that describe specific jobs other than acting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence provides direct evidence of work being done by both actors and technical crew, proving the production involved tasks beyond just acting.","incorrect":["",{"choice":"A math poster showed different kinds of triangles.","category":"irrelevant information","reason":"This detail describes a math poster, which has nothing to do with the roles or work required to produce a school play."},{"choice":"The passage says every reader already knew about school play.","category":"not supported by text","reason":"This statement is not found in the passage and does not explain how the play was created or who worked on it."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"While a title might name a topic, it does not provide the specific actions or examples needed to support the claim about what was required for the production."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":68,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0069","version":3,"contentHash":"sha256:57bcf267e5b592501fa73431935ae21890b465e330ed474a0d01aff2a0aaadde","question":"Read the passage. Grade 3 developing passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. These details show that cafeteria food scraps were collected and turned into compost for flowers.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["A new scoreboard was installed in the gym.","After several weeks, the dark compost was mixed into flower beds.","The passage says every reader already knew about compost bin.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting details are specific facts or sentences in a text that provide evidence for the main idea.","example":"Main idea: Dogs are helpful. Supporting detail: A golden retriever helped the person find their lost keys.","strategyClue":"Find the main idea first, then look for the sentence that specifically describes the action of turning waste into something productive or beneficial.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence shows that the scraps were turned into something useful (compost for flowers) rather than being thrown in the trash.","incorrect":[{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This sentence describes the gym, not the cafeteria food scraps, so it does not support the idea that food scraps can be useful."},"",{"choice":"The passage says every reader already knew about compost bin.","category":"incorrect text reference","reason":"This sentence does not appear in the passage and does not provide evidence for how food scraps are recycled."},{"choice":"The title names the topic but gives no proof.","category":"not a passage sentence","reason":"This is a comment about the passage, not a sentence from the story itself, and it fails to explain how scraps are reused."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":69,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0070","version":3,"contentHash":"sha256:82fd1b2a67cdc0f2c30ba9b7ccf200360911075c0320c882c1b19d932a572d2d","question":"Read the passage. Grade 3 developing passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. These details show that science students recorded weather measurements and used them to find patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The passage says every reader already knew about weather station.","The music teacher tuned a violin before class.","They measured rainfall, wind direction, temperature, and cloud cover every day.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Evidence is a specific fact, quote, or detail from a text that proves an idea or answer is correct.","example":"Claim: The dog is hungry. Evidence: The dog is barking at its empty food bowl.","strategyClue":"Look for the sentence in the text that lists multiple examples or specific items related to the claim. Avoid sentences that describe different subjects or sentences that are just general opinions.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. Evidence is specific information from the text that supports a claim. This sentence lists four distinct types of data the students tracked, which directly proves they gathered more than one kind of weather information.","incorrect":[{"choice":"The passage says every reader already knew about weather station.","category":"Unsupported by text","reason":"This statement is not found in the passage, and even if it were, it does not explain how the students collected specific weather data."},{"choice":"The music teacher tuned a violin before class.","category":"Irrelevant information","reason":"This sentence describes a completely different topic (music) and provides no evidence regarding the weather measurements taken by the students."},"",{"choice":"The title names the topic but gives no proof.","category":"Unclear evidence source","reason":"Titles often introduce a topic, but they rarely provide the specific data points or observations needed to prove a claim about a process."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":70,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0071","version":3,"contentHash":"sha256:ef3d6e52ee86d3acc52bd9c2f75a1f3599f88cb046525246464c5f0ac13de761","question":"Read the passage. Grade 3 developing passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. These details show that a recycling team used bins and reminders to reduce paper waste.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The title names the topic but gives no proof.","The nurse checked the first-aid supplies after lunch.","The passage says every reader already knew about recycling team.","By winter break, the school ordered fewer boxes of printer paper."],"correct":3,"studyAid":{"definition":"Supporting details are facts or evidence from the text that explain why a main idea is true.","example":"Main idea: My dog is helpful. Supporting detail: He carries the newspaper to the door every morning.","strategyClue":"Look for a sentence that provides a measurement or result. Ask yourself, 'Which sentence shows the direct result of the recycling team's actions?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides factual evidence of a reduction in paper usage, which directly supports the idea that the plan changed how much paper the school used.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not a sentence","reason":"This is not a sentence from the passage, and it does not provide evidence of how much paper was used."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"irrelevant information","reason":"This sentence mentions a nurse and first-aid supplies, which are unrelated to the topic of paper recycling and waste reduction."},{"choice":"The passage says every reader already knew about recycling team.","category":"not in text","reason":"This sentence is not found in the provided passage and does not show proof of the team's impact on paper waste."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":71,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0072","version":3,"contentHash":"sha256:451e380aec9202a080cf785fe6ab22a74b06e5c8d127f609d1640963bed82841","question":"Read the passage. Grade 3 developing passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. These details show that museum workers created an exhibit that helped visitors learn local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["Visitors could press buttons to hear recordings of elders telling memories.","A rainstorm delayed the baseball game.","The passage says every reader already knew about museum exhibit.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find the strongest evidence, look for the specific sentence in the text that directly matches the keywords and ideas presented in the question.","example":"Question: How did the boy show he was sad? Text: 'The boy cried when his balloon popped.' Evidence: 'The boy cried when his balloon popped.'","strategyClue":"Scan the text for keywords from the question like 'objects' or 'stories.' Then, check each option to see which one explicitly describes those items being part of the exhibit.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides direct proof of 'personal stories' (the recordings of elders) and 'objects' (the exhibit context provided earlier in the passage).","incorrect":["",{"choice":"A rainstorm delayed the baseball game.","category":"irrelevant information","reason":"This detail describes a sporting event and is not mentioned anywhere in the passage about museum exhibits or history."},{"choice":"The passage says every reader already knew about museum exhibit.","category":"false information","reason":"The passage never mentions what the readers already know; it focuses entirely on the actions of the museum workers and the visitors."},{"choice":"The title names the topic but gives no proof.","category":"invalid logic","reason":"The question asks for the strongest evidence found in the passage's details, not the title, and the evidence must directly relate to the objects and stories."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":72,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0073","version":3,"contentHash":"sha256:01ff5b835f47e2353a59292acece9580f6556893bb39dc4c9105960082bf0af0","question":"Read the passage. Grade 3 developing passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. These details show that club members tested a robot, changed its code, and used notes to improve it.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["The principal announced picture day over the speaker.","Each time the robot missed a turn, members adjusted the code and tested again.","The passage says every reader already knew about robotics club.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence is a specific sentence or detail from the text that proves your answer is true.","example":"Claim: The dog was hungry. Evidence: He whined and scratched at his empty food bowl.","strategyClue":"Look for the sentence that describes the club members reacting to a specific problem or error. Ask yourself, 'Which sentence shows them learning something new because something went wrong?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the club learning from an error (the robot missing a turn) and using that information to change their work, which directly supports the idea of using mistakes as information.","incorrect":[{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This sentence is about an announcement, not the robotics club. It has nothing to do with the robot or learning from mistakes."},"",{"choice":"The passage says every reader already knew about robotics club.","category":"inaccurate claim","reason":"The passage never states that every reader knows about the club. Always stick to the facts provided in the text."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a subject, but it does not describe the specific actions the members took to learn from their mistakes during testing."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":73,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0074","version":3,"contentHash":"sha256:a4ad941eb2d4648d7e3c26f8311360eadb38d13df8d3a9c4fc0269c2d37a2c95","question":"Read the passage. Grade 3 developing passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. These details show that school leaders made breakfast easier for busy students to get.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The passage says every reader already knew about school breakfast.","The science lab received new magnifying glasses.","Students who arrived close to the bell could still choose a quick meal.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly proves or supports a claim or main idea.","example":"Claim: The dog was hungry. Evidence: He ate his entire bowl of food in ten seconds.","strategyClue":"Look at the key words in the question—in this case, 'little time'—and scan the text for a sentence that describes a specific situation involving time constraints.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This detail directly addresses the 'little time' aspect by showing that even late-arriving students had a way to access breakfast.","incorrect":[{"choice":"The passage says every reader already knew about school breakfast.","category":"not in text","reason":"This information is not mentioned in the passage and does not explain why the cart was designed for students with little time."},{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This detail is completely unrelated to the breakfast cart or the time constraints students might face in the morning."},"",{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title is not evidence. You need to look for specific actions or behaviors in the text that prove the goal of the breakfast cart."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":74,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0075","version":3,"contentHash":"sha256:f7377ec89f536e4b6c8b22d119c4cb54c375ee835e5490c321d60577af8da361","question":"Read the passage. Grade 3 developing passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. These details show that park rangers marked a trail so visitors could navigate and learn.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The title names the topic but gives no proof.","The post office closed early on Saturday.","The passage says every reader already knew about nature trail.","They added arrows, distance signs, and small plaques naming common trees."],"correct":3,"studyAid":{"definition":"Supporting evidence consists of specific details or facts from the text that directly explain or prove why a main idea is true.","example":"Main Idea: 'Dogs are helpful pets.' Supporting evidence: 'They can be trained to help people see and can keep houses safe.'","strategyClue":"Look for a sentence that contains evidence for BOTH parts of the claim (directions and information). Ask yourself, 'Does this sentence show the rangers providing both types of help?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence directly provides evidence for both directions (arrows, signs) and information (plaques naming common trees).","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The title usually introduces a topic, but it does not contain the specific facts or evidence needed to support a claim about what the signs provided."},{"choice":"The post office closed early on Saturday.","category":"off-topic sentence","reason":"This sentence is not about park rangers or trails; it introduces an entirely different subject that has no connection to the passage provided."},{"choice":"The passage says every reader already knew about nature trail.","category":"not in text","reason":"This statement is not found in the passage, and even if it were, knowing about a trail does not prove what the signs were used for."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":75,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0076","version":3,"contentHash":"sha256:0ecbc81bf557e0fbd8916b209d1878f5d484c3f5db02fc228a5638af0187db3d","question":"Read the passage. Grade 3 challenge passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong. Because the passage connects actions with results, readers can see why daily care helped the school garden grow well.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["They recorded how tall the seedlings grew.","The art room displayed clay bowls near the window.","The passage says every reader already knew about school garden.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support a claim, choose a sentence from the text that provides factual evidence or specific actions that prove the claim is true.","example":"Claim: 'The dog was hungry.' Evidence: 'The dog nudged his empty bowl with his nose.'","strategyClue":"Look for a sentence that describes a specific action related to the claim. Ask yourself, 'Does this sentence show the students actually doing the action mentioned in the claim?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence directly describes the students taking measurements (observations) of the plants to track their growth, which is a method of caring for them.","incorrect":["",{"choice":"The art room displayed clay bowls near the window.","category":"irrelevant information","reason":"This sentence describes art supplies, not the school garden or observations made by students. It does not relate to the claim about plant care."},{"choice":"The passage says every reader already knew about school garden.","category":"unsupported claim","reason":"This statement is not present in the text and does not provide any evidence that the students used observations to help the plants grow."},{"choice":"The title names the topic but gives no proof.","category":"meta-analysis error","reason":"The title is not a sentence from the passage that shows how the students cared for the plants; it is a description of the text structure, not evidence of plant care."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":76,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0077","version":3,"contentHash":"sha256:c57be958007dc09f6b67bb9e638071eb03cf6fa561d56e4aba535996ffb4931e","question":"Read the passage. Grade 3 challenge passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books. Because the passage connects actions with results, readers can see why student helpers organized the library so readers could find books faster.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["The cafeteria served tomato soup on Thursday.","They sorted returned books by call number before placing them on shelves.","The passage says every reader already knew about library helpers.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting evidence must directly relate to the main idea or the claim being discussed in a text.","example":"Claim: 'The garden was well-tended.' Evidence: 'The flowers were neatly trimmed and watered daily.' (Not: 'The garden had a fence.')","strategyClue":"Search the text for an action that creates a logical system for finding items, then ask yourself: 'Does this action make it faster or easier for a library user to find what they need?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains the system used to organize books, which allows readers to locate specific materials quickly by their unique call numbers.","incorrect":[{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This information is not found in the passage and has no connection to library organization or how students help readers find books."},"",{"choice":"The passage says every reader already knew about library helpers.","category":"unsupported claim","reason":"The passage never mentions what readers knew; it focuses on the actions taken by student volunteers to make the library easier to use."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"This choice describes a title, but it does not provide an actual detail from the text that proves the efficiency of the volunteers' work."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":77,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0078","version":3,"contentHash":"sha256:44654af3e2230d70137d86a69338733671d95150910edb74c0ed4b75a13f7cc8","question":"Read the passage. Grade 3 challenge passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose. Because the passage connects actions with results, readers can see why a rain barrel helped the club save water for plants.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["The passage says every reader already knew about rain barrel.","A soccer team practiced corner kicks after school.","Members used the stored water on dry afternoons instead of turning on the hose.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support a main idea, look for specific evidence or examples in the text that directly show the 'why' or 'how' of the statement.","example":"Main idea: 'The park is great for sports.' Supporting detail: 'There are two tennis courts and a large soccer field.'","strategyClue":"Look for the sentence that describes a specific action the members took that results in using less water from the hose.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly describes the action of using rainwater in place of the hose, which serves as clear evidence that the rain barrel reduced the need for hose water.","incorrect":[{"choice":"The passage says every reader already knew about rain barrel.","category":"Unsupported detail","reason":"The passage does not state that readers already knew about rain barrels, and this choice does not provide evidence that water was saved."},{"choice":"A soccer team practiced corner kicks after school.","category":"Off-topic information","reason":"This sentence is completely unrelated to the science club or the use of a rain barrel, so it cannot support the main idea."},"",{"choice":"The title names the topic but gives no proof.","category":"Irrelevant observation","reason":"While a title might name a topic, it does not provide the specific proof or evidence needed to show how the club saved water."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":78,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0079","version":3,"contentHash":"sha256:9e5964cf70325467217bcf5c8e9853b9abdb8f4117f2f93439cac8a18a2479a0","question":"Read the passage. Grade 3 challenge passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey. Because the passage connects actions with results, readers can see why the class newspaper gave students a careful way to share school news.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The title names the topic but gives no proof.","The playground slide was painted blue over spring break.","The passage says every reader already knew about class newspaper.","They interviewed teachers, wrote short articles, and checked facts before printing."],"correct":3,"studyAid":{"definition":"Evidence is a piece of information from the text that directly supports your answer to a question.","example":"Question: Was the character sad? Evidence: 'He sighed deeply and wiped a tear from his cheek.'","strategyClue":"Look for keywords in the question, such as 'accurate' or 'checked,' then scan the text to find which sentence describes actions that match those specific words.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. This choice provides direct evidence of the reporters' deliberate actions, such as 'checking facts,' which clearly shows an effort to maintain accuracy.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The passage does not mention a title for the newspaper, and even if it did, a title does not describe the actions the reporters took to be accurate."},{"choice":"The playground slide was painted blue over spring break.","category":"unrelated content","reason":"This sentence provides information about a playground, which is completely unrelated to the production or the accuracy of the school newspaper."},{"choice":"The passage says every reader already knew about class newspaper.","category":"factually incorrect statement","reason":"The passage does not state that readers already knew about the newspaper; this choice is not supported by the text and does not address the topic of accuracy."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":79,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0080","version":3,"contentHash":"sha256:076918d276284333934cc3db34a2d81be8c796d28f72d8e67f6c0a37d474c77b","question":"Read the passage. Grade 3 challenge passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash. Because the passage connects actions with results, readers can see why the cleanup protected the beach by removing harmful litter.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["They filled ten bags with plastic wrappers, bottle caps, and broken fishing line.","The town band played a concert in the park.","The passage says every reader already knew about beach cleanup.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To support a claim, choose the evidence that directly explains or shows how the claim is true.","example":"Claim: 'The rain helped the garden grow.' Evidence: 'Flowers bloomed after the heavy rainfall.'","strategyClue":"Identify the key words in the claim, such as 'safer' or 'wildlife', and look for the specific action in the text that removes a danger related to those words.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence that the beach is now safer because specific harmful items, which could injure wildlife, were removed from the sand.","incorrect":["",{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence describes an event unrelated to the beach cleanup and provides no evidence about beach safety or wildlife."},{"choice":"The passage says every reader already knew about beach cleanup.","category":"unsupported claim","reason":"The passage does not state that readers already knew about the cleanup; this is a claim that is not supported by the text provided."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a topic, but it does not act as evidence to support the claim that the beach became safer for wildlife."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":80,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0081","version":3,"contentHash":"sha256:a615cf61e047157378528e7ccbe1b65652992243b51bc429cb7e7eb7f1e02cd3","question":"Read the passage. Grade 3 challenge passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors. Because the passage connects actions with results, readers can see why bike riders can prevent injuries by following safety rules.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["The school choir rehearsed a song about the moon.","She showed how helmets should sit flat and snug on a rider's head.","The passage says every reader already knew about bike safety.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence for a claim, look for the sentence in the text that provides the most direct explanation or proof for that specific idea.","example":"Claim: 'Dogs are helpful.' Evidence: 'My dog helps me find my lost keys every morning.' vs. 'My dog is brown.'","strategyClue":"Highlight the key words in the claim, such as 'helmet' and 'fit.' Then, scan the text specifically for sentences that explain the condition or placement of the helmet.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides specific instructions on the proper fit of a helmet, which directly supports the claim that a helmet must fit correctly to protect the rider.","incorrect":[{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This detail is not found in the passage and has nothing to do with bike safety or helmet fit."},"",{"choice":"The passage says every reader already knew about bike safety.","category":"unsupported claim","reason":"The passage does not state that readers already knew about safety; it focuses on the instructions provided by the officer."},{"choice":"The title names the topic but gives no proof.","category":"missing textual evidence","reason":"While a title might name a topic, the question asks for evidence found within the text that supports a specific claim about helmet fit."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":81,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0082","version":3,"contentHash":"sha256:2460ef4622255b7bfc74dcc0e494f468b74f469c58ce5159a1e91f555eee45b9","question":"Read the passage. Grade 3 challenge passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes. Because the passage connects actions with results, readers can see why new bus routes made important places easier to reach.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["The passage says every reader already knew about city buses.","A bakery sold cinnamon rolls before sunrise.","The new route stopped near the clinic, grocery store, and community center.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To support a main idea, choose evidence that directly connects to the specific claim being made.","example":"Claim: 'The park is fun.' Evidence: 'The park has a large playground, a swimming pool, and a snack bar.' (Not: 'The park has a parking lot.')","strategyClue":"Look for keywords from the main idea, like 'community' or 'needs', and find the sentence that lists specific places or services that help people in that community.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence provides specific locations that serve the public, directly supporting the idea that the bus route helps fulfill community needs.","incorrect":[{"choice":"The passage says every reader already knew about city buses.","category":"unsupported information","reason":"This statement is not found in the text and does not describe the bus route's purpose or community value."},{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence mentions a business, but it is not part of the passage provided and does not relate to transportation planners or bus routes."},"",{"choice":"The title names the topic but gives no proof.","category":"meta-analysis error","reason":"This choice comments on the structure of a text rather than providing a piece of evidence from the passage that proves the bus route served community needs."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":82,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0083","version":3,"contentHash":"sha256:14f5af6c4f81a5b09e555fc90cec0a050f5490289dc31553eed605bca7bcc731","question":"Read the passage. Grade 3 challenge passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began. Because the passage connects actions with results, readers can see why many students worked together to prepare the school play.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["The title names the topic but gives no proof.","A math poster showed different kinds of triangles.","The passage says every reader already knew about school play.","Actors practiced lines while stage crew members painted scenery and tested lights."],"correct":3,"studyAid":{"definition":"To find the strongest evidence, look for specific details in the text that directly support or prove the main claim being made.","example":"Claim: The weather was bad. Evidence: The rain flooded the streets and the wind knocked down trees.","strategyClue":"Identify the key parts of the claim you are trying to support. Scan the text specifically for sentences that describe the different jobs or roles required for the play beyond just 'acting.'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence explicitly lists tasks performed by both actors and stage crew, showing that the production depended on more than just the performance of lines.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"The title is not provided in the passage, and even if it were, a title only labels the subject rather than providing evidence of how the work was done."},{"choice":"A math poster showed different kinds of triangles.","category":"unrelated detail","reason":"This information is not mentioned in the passage and has no connection to the work involved in producing a school play."},{"choice":"The passage says every reader already knew about school play.","category":"unsupported claim","reason":"The passage never mentions what the reader knows; it focuses on the actions taken by the students to complete the play."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":83,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0084","version":3,"contentHash":"sha256:bfebaf97e26ac03a07fff12bd22d6f794ec72914e202530e143d7c8a7ae4865d","question":"Read the passage. Grade 3 challenge passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds. Because the passage connects actions with results, readers can see why composting changed cafeteria scraps into useful soil material.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["After several weeks, the dark compost was mixed into flower beds.","A new scoreboard was installed in the gym.","The passage says every reader already knew about compost bin.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence is a detail, fact, or example from the text that directly proves the main point or idea.","example":"Main idea: Dogs are helpful. Supporting detail: A golden retriever helped the family find their lost keys.","strategyClue":"Identify the key concept in the prompt (useful soil) and look for the specific action in the text that shows that change happening.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence provides evidence that the scraps were put to use (in flower beds) rather than being thrown in the trash.","incorrect":["",{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This sentence describes a gym, not the cafeteria food scraps. It does not provide any evidence about composting."},{"choice":"The passage says every reader already knew about compost bin.","category":"unsupported claim","reason":"This is a statement about the reader's knowledge, not an action from the passage that shows food scraps becoming useful."},{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This is a comment about how the text is written rather than an actual event or detail from the story that proves food scraps can be used for soil."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":84,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0085","version":3,"contentHash":"sha256:0a58fcfe91cb77204208f5a2a2e74706dcaf2bf3d85ddf3f4943a2b28eb9ed7f","question":"Read the passage. Grade 3 challenge passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights. Because the passage connects actions with results, readers can see why students collected weather data to notice local patterns.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["The music teacher tuned a violin before class.","They measured rainfall, wind direction, temperature, and cloud cover every day.","The passage says every reader already knew about weather station.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly supports or proves a point.","example":"Claim: The classroom is busy. Evidence: Students are writing, painting, and reading at different tables.","strategyClue":"Look for a sentence that lists specific examples or measurements; count how many different items or actions are mentioned to see if they support the idea of 'more than one'.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data collected, proving the students gathered more than one kind of evidence.","incorrect":[{"choice":"The music teacher tuned a violin before class.","category":"irrelevant information","reason":"This sentence is not about science students or weather. It does not provide any evidence regarding the data collection process mentioned in the passage."},"",{"choice":"The passage says every reader already knew about weather station.","category":"unsupported claim","reason":"The passage does not state this information at all. Even if it were true, knowing about a station does not prove that multiple types of evidence were gathered."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"Titles often introduce topics, but they do not list the specific measurements taken during a study. This choice fails to support the claim about gathering multiple kinds of data."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":85,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0086","version":3,"contentHash":"sha256:604a6520f090c8e963347958921553c0200663b91858f882630837d218612f9d","question":"Read the passage. Grade 3 challenge passage: A recycling team reduced paper waste at school. They placed blue bins in classrooms and reminded students to use both sides of paper. By winter break, the school ordered fewer boxes of printer paper. Because the passage connects actions with results, readers can see why the recycling team helped the school waste less paper.\n\nWhich sentence from the passage best supports this idea: The plan changed how much paper the school used.","choices":["The passage says every reader already knew about recycling team.","The nurse checked the first-aid supplies after lunch.","By winter break, the school ordered fewer boxes of printer paper.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting details are facts or evidence from the text that explain why a main idea is true.","example":"Claim: The garden grew well. Evidence: We picked twenty ripe tomatoes in July.","strategyClue":"Look for a sentence that describes a measurable result or a specific consequence that proves the main action actually caused a change.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: By winter break, the school ordered fewer boxes of printer paper. This sentence provides factual evidence of a change in paper consumption, which directly supports the claim that the recycling plan impacted how much paper the school used.","incorrect":[{"choice":"The passage says every reader already knew about recycling team.","category":"not supported by text","reason":"This statement is not found in the passage and does not provide any evidence about the school's paper usage habits."},{"choice":"The nurse checked the first-aid supplies after lunch.","category":"unrelated to topic","reason":"This sentence mentions a different person and a different activity entirely; it does not relate to the recycling plan or paper usage."},"",{"choice":"The title names the topic but gives no proof.","category":"missing evidentiary support","reason":"While titles describe a topic, they do not provide the specific data needed to prove that a change in behavior actually occurred."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":86,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0087","version":3,"contentHash":"sha256:85de4f06e444290e7684da03acbf843f7357eb91e233ea1711b23749495044e2","question":"Read the passage. Grade 3 challenge passage: Museum workers built an exhibit about local history. They displayed old tools, photographs, letters, and a map of the first town road. Visitors could press buttons to hear recordings of elders telling memories. Because the passage connects actions with results, readers can see why the exhibit used artifacts and voices to teach local history.\n\nWhich detail is the strongest evidence for the answer, \"The exhibit included both objects and personal stories.\"?","choices":["The title names the topic but gives no proof.","A rainstorm delayed the baseball game.","The passage says every reader already knew about museum exhibit.","Visitors could press buttons to hear recordings of elders telling memories."],"correct":3,"studyAid":{"definition":"To find evidence in a text, look for the specific sentences that directly name or describe the parts of the idea you are trying to prove.","example":"Claim: 'The pet store had many animals.' Evidence: 'The store was filled with barking dogs, chirping birds, and swimming goldfish.'","strategyClue":"Break the claim into two parts: 'objects' and 'personal stories.' Scan the text to find the exact words that name an item to touch or see, and the words that involve hearing someone speak.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Visitors could press buttons to hear recordings of elders telling memories. This sentence provides direct evidence for the 'personal stories' component, while the mention of 'old tools, photographs, [and] letters' supports the 'objects' component of the exhibit.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant reasoning","reason":"The passage does not mention a title or a specific name for the exhibit, so this choice does not provide evidence from the text."},{"choice":"A rainstorm delayed the baseball game.","category":"off-topic information","reason":"This information is not found in the passage and does not relate to the museum exhibit or the claim about objects and stories."},{"choice":"The passage says every reader already knew about museum exhibit.","category":"unsupported claim","reason":"The text never claims that readers already knew about the exhibit; in fact, it explains what the exhibit included for the readers."},""]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":87,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0088","version":3,"contentHash":"sha256:819fa763b6d7f88e535818f291b0325b6999c9b16e208507299994a5947650ad","question":"Read the passage. Grade 3 challenge passage: Club members improved a robot through testing. Each time the robot missed a turn, members adjusted the code and tested again. They kept notes about which wheel speed worked best on the course. Because the passage connects actions with results, readers can see why testing and revising helped the robotics club improve its robot.\n\nWhich sentence from the passage best supports this idea: The club used mistakes as information.","choices":["Each time the robot missed a turn, members adjusted the code and tested again.","The principal announced picture day over the speaker.","The passage says every reader already knew about robotics club.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Supporting evidence is a piece of information from the text that proves or explains a claim or an idea.","example":"Claim: The dog was hungry. Supporting evidence: The dog barked and nudged his empty food bowl with his nose.","strategyClue":"Look for a sentence that describes a specific action, observation, or result that proves the club members were paying attention to what went wrong.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Each time the robot missed a turn, members adjusted the code and tested again. This sentence shows the club learning from a 'mistake' (missing a turn) by making an adjustment, which directly supports the idea that they used mistakes as information.","incorrect":["",{"choice":"The principal announced picture day over the speaker.","category":"irrelevant information","reason":"This sentence mentions a principal and pictures, which has nothing to do with robotics, testing, or learning from mistakes."},{"choice":"The passage says every reader already knew about robotics club.","category":"unsupported claim","reason":"This statement is not found in the text and does not provide any evidence that the club used mistakes to improve their project."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"Even if a title describes a topic, it does not show the process of turning mistakes into information like a specific action in the story does."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":88,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0089","version":3,"contentHash":"sha256:6f82679056a48306c1077cbdedafadc3e9d068803520dbfa308d625ad0b796e1","question":"Read the passage. Grade 3 challenge passage: School leaders started a breakfast cart. The cart offered fruit, yogurt, and whole-grain muffins near the front door. Students who arrived close to the bell could still choose a quick meal. Because the passage connects actions with results, readers can see why the breakfast cart helped more students start the day with food.\n\nWhich detail is the strongest evidence for the answer, \"The cart was designed for students with little time before class.\"?","choices":["The science lab received new magnifying glasses.","Students who arrived close to the bell could still choose a quick meal.","The passage says every reader already knew about school breakfast.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Strong evidence is a specific fact or detail from the text that directly proves or supports a claim or main idea.","example":"Claim: The park was popular. Evidence: The swings were always full and there was a line for the slide.","strategyClue":"Look for a sentence in the passage that links the 'breakfast cart' to the specific challenge of having 'little time.' Ignore sentences that mention different topics or offer general opinions.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Students who arrived close to the bell could still choose a quick meal. This sentence shows that the cart accommodated students arriving late or in a hurry, which directly supports the claim that the cart was designed for students with little time.","incorrect":[{"choice":"The science lab received new magnifying glasses.","category":"irrelevant information","reason":"This detail mentions a science lab and magnifying glasses, which have nothing to do with the breakfast cart or student breakfast habits."},"",{"choice":"The passage says every reader already knew about school breakfast.","category":"unsupported claim","reason":"This statement is not found in the text and does not provide evidence about how the cart helps students who have very little time before class starts."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a topic, but it does not provide the specific details or evidence needed to prove why the cart is helpful for busy students."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":89,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0090","version":3,"contentHash":"sha256:ac4006dd959f8cf6e7689f7235094497f309e1f9bea3fc6bb628d91c586a4660","question":"Read the passage. Grade 3 challenge passage: Park rangers marked a trail for visitors. They added arrows, distance signs, and small plaques naming common trees. A new bench gave hikers a place to rest near the creek. Because the passage connects actions with results, readers can see why trail signs helped visitors move safely and learn about nature.\n\nWhich sentence from the passage best supports this idea: The signs gave visitors both directions and information.","choices":["The passage says every reader already knew about nature trail.","The post office closed early on Saturday.","They added arrows, distance signs, and small plaques naming common trees.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Supporting evidence is a specific sentence or detail from the text that directly proves a claim or idea is true.","example":"Claim: 'The weather changed.' Evidence: 'Dark clouds appeared and the temperature dropped suddenly.'","strategyClue":"Identify the two main parts of the claim—'directions' and 'information'—then look for a sentence that specifically lists examples of both.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They added arrows, distance signs, and small plaques naming common trees. This sentence provides specific evidence that the park rangers included both directions (arrows, distance signs) and information (plaques naming trees) to help visitors.","incorrect":[{"choice":"The passage says every reader already knew about nature trail.","category":"unsupported text claim","reason":"This information does not appear in the text provided. When finding supporting evidence, ensure the fact is actually stated in the passage."},{"choice":"The post office closed early on Saturday.","category":"irrelevant information","reason":"This sentence is completely unrelated to the topic of park trails, hikers, or signs. It does not provide evidence for the idea being discussed."},"",{"choice":"The title names the topic but gives no proof.","category":"misunderstanding evidence","reason":"The prompt asks for a sentence that proves the claim. This choice describes why something might *not* be good evidence rather than providing the evidence itself."}]},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":90,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0091","version":3,"contentHash":"sha256:01af2185ebbd1e1060d16a06e52fc174e502ee470d1e13396f6ded6dfe61ee76","question":"Read the passage. Grade 4 foundation passage: A class kept a school garden healthy. Students watered the seedlings each morning and recorded how tall they grew. They also moved the shade cloth when the afternoon sun became too strong.\n\nWhich sentence from the passage best supports this idea: The students used observations to care for the plants.","choices":["The title names the topic but gives no proof.","The art room displayed clay bowls near the window.","The passage says every reader already knew about school garden.","They recorded how tall the seedlings grew."],"correct":3,"studyAid":{"definition":"To find evidence for an idea, look for a sentence that describes an action or specific detail directly related to that idea.","example":"Idea: The dog was tired. Evidence: The dog curled up on the rug and fell fast asleep.","strategyClue":"Look for the keyword 'observations' or 'recorded' in the text and match it to a specific task the students performed in the garden.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They recorded how tall the seedlings grew. This sentence provides direct evidence because recording the height of the plants is a way of observing their growth to help keep them healthy.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"irrelevant information","reason":"Titles often introduce a topic, but they rarely provide the specific actions or observations needed to prove how students cared for the plants."},{"choice":"The art room displayed clay bowls near the window.","category":"off-topic sentence","reason":"This sentence mentions a window, but it is about clay bowls in an art room, which has nothing to do with gardening or observing plant growth."},{"choice":"The passage says every reader already knew about school garden.","category":"unsupported information","reason":"This statement is not found in the text, and even if it were, it does not explain how the students performed observations to care for the garden."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":91,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0092","version":3,"contentHash":"sha256:7347b1426bfc6da9afa24b8cce793b52e68f48f0f1b72e78fa8cb5bf6fd952ab","question":"Read the passage. Grade 4 foundation passage: Student volunteers made the library easier to use. They sorted returned books by call number before placing them on shelves. They made bright shelf labels for mystery, science, and biography books.\n\nWhich detail is the strongest evidence for the answer, \"The volunteers helped readers find materials more efficiently.\"?","choices":["They sorted returned books by call number before placing them on shelves.","The cafeteria served tomato soup on Thursday.","The passage says every reader already knew about library helpers.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence must be a specific fact from the text that directly supports the claim or argument being made.","example":"Claim: The dog is fast. Evidence: The dog won the neighborhood race in record time. (Not evidence: The dog has soft fur.)","strategyClue":"Identify the key action in the claim, then look for the sentence in the text that describes the 'how' or 'why' behind that action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They sorted returned books by call number before placing them on shelves. This detail directly explains how books are organized, which helps readers locate specific materials much faster.","incorrect":["",{"choice":"The cafeteria served tomato soup on Thursday.","category":"irrelevant information","reason":"This sentence describes food, which has no connection to the library, books, or helping readers find materials."},{"choice":"The passage says every reader already knew about library helpers.","category":"unsupported claim","reason":"This information is not found in the passage and does not explain how the library became easier to use."},{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title is just a heading; it does not contain the specific actions that prove the volunteers actually made the library more efficient."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":92,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0093","version":3,"contentHash":"sha256:051cdea69a62bc4fea0577cda7df51a157407e1bdd740354c63bef4d48bed82d","question":"Read the passage. Grade 4 foundation passage: A science club collected rainwater for outdoor plants. The barrel caught water from the roof during storms. Members used the stored water on dry afternoons instead of turning on the hose.\n\nWhich sentence from the passage best supports this idea: The rain barrel reduced the need for hose water.","choices":["A soccer team practiced corner kicks after school.","Members used the stored water on dry afternoons instead of turning on the hose.","The passage says every reader already knew about rain barrel.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"Supporting details are specific sentences in a text that provide evidence or examples to back up a main idea or claim.","example":"Claim: Dogs are helpful. Detail: My dog helps carry the groceries inside.","strategyClue":"Identify the key nouns and verbs in the claim, such as 'hose' and 'need,' then search the passage for sentences that describe actions related to those specific words.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Members used the stored water on dry afternoons instead of turning on the hose. This sentence directly shows how the barrel replaced the need for the hose by describing the action taken instead of using the hose.","incorrect":[{"choice":"A soccer team practiced corner kicks after school.","category":"irrelevant information","reason":"This sentence is not part of the passage and does not mention rain barrels, water, or hoses at all."},"",{"choice":"The passage says every reader already knew about rain barrel.","category":"incorrect claim","reason":"This is a statement about the passage itself, not a sentence from the text, and it does not provide evidence for the usage of the barrel."},{"choice":"The title names the topic but gives no proof.","category":"meta-commentary error","reason":"This choice discusses the structure of a title rather than providing evidence from the text to support the claim about reducing hose water."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":93,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0094","version":3,"contentHash":"sha256:729ed8ae5f69e102d87605e68df9036ad8b4ec74a2c46daacb90e41dbcc511e5","question":"Read the passage. Grade 4 foundation passage: Young reporters created a newspaper for their school. They interviewed teachers, wrote short articles, and checked facts before printing. The first issue included a sports column, a book review, and a lunch survey.\n\nWhich detail is the strongest evidence for the answer, \"The reporters tried to make the newspaper accurate.\"?","choices":["The passage says every reader already knew about class newspaper.","The playground slide was painted blue over spring break.","They interviewed teachers, wrote short articles, and checked facts before printing.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"To find the best evidence for a claim, look for specific actions or descriptions in the text that directly support that claim.","example":"Claim: The baker worked hard. Evidence: She spent all night kneading dough and cleaning the kitchen.","strategyClue":"Highlight the key words in the question, then scan the passage for sentences that describe the reporters doing work related to those specific keywords.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They interviewed teachers, wrote short articles, and checked facts before printing. Checking facts is the direct process of ensuring information is correct and truthful, which provides clear evidence for accuracy.","incorrect":[{"choice":"The passage says every reader already knew about class newspaper.","category":"not in text","reason":"This information is not found in the passage, and it does not explain how the reporters ensured their writing was accurate."},{"choice":"The playground slide was painted blue over spring break.","category":"irrelevant detail","reason":"This detail describes the playground, which has nothing to do with the creation of the newspaper or the reporters' methods."},"",{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"A title or name of a newspaper does not provide evidence of the quality or the accuracy of the work inside."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":94,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0095","version":3,"contentHash":"sha256:a90dbec780a29fa378b138ac4f86455493980c72649848e1e986dd3a4bb75c18","question":"Read the passage. Grade 4 foundation passage: Families removed litter from the beach. They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. Afterward, volunteers posted signs reminding visitors to pack out trash.\n\nWhich sentence from the passage best supports this idea: The cleanup made the beach safer for wildlife.","choices":["The title names the topic but gives no proof.","The town band played a concert in the park.","The passage says every reader already knew about beach cleanup.","They filled ten bags with plastic wrappers, bottle caps, and broken fishing line."],"correct":3,"studyAid":{"definition":"To find evidence that supports an idea, look for specific details or actions in the text that directly relate to the claim.","example":"Claim: The weather was bad. Evidence: It rained all afternoon and the wind blew down our umbrella.","strategyClue":"Look for the sentence that describes the physical items removed. Think about which items are dangerous to animals and how taking them away helps.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They filled ten bags with plastic wrappers, bottle caps, and broken fishing line. This sentence provides evidence of safety by showing how the volunteers removed dangerous items like fishing line and bottle caps that could harm wildlife.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not in text","reason":"This is a comment about a title, but the passage provided does not actually include a title to evaluate."},{"choice":"The town band played a concert in the park.","category":"irrelevant information","reason":"This sentence is not part of the passage and does not mention beach cleanup or wildlife safety at all."},{"choice":"The passage says every reader already knew about beach cleanup.","category":"incorrect inference","reason":"The text describes what the volunteers did, but it never makes a claim about what the readers already know."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":95,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0096","version":3,"contentHash":"sha256:fd77e750c3b71ed34259f267ed5400aea041a3e265a64c70b09aa202da8cc3be","question":"Read the passage. Grade 4 foundation passage: A safety officer taught students how to ride bikes safely. She showed how helmets should sit flat and snug on a rider's head. She reminded riders to signal turns and watch for opening car doors.\n\nWhich detail is the strongest evidence for the answer, \"A helmet must fit correctly to protect a rider.\"?","choices":["She showed how helmets should sit flat and snug on a rider's head.","The school choir rehearsed a song about the moon.","The passage says every reader already knew about bike safety.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"Strong evidence is a specific sentence or detail from the text that directly supports a main idea or a claim about what the text says.","example":"Claim: Dogs are helpful pets. Evidence: They can be trained to help people find lost items or guard homes.","strategyClue":"Identify the key words in the claim—in this case, 'helmet', 'fit', and 'protect'—then look for the sentence that provides the most specific details about those exact topics.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She showed how helmets should sit flat and snug on a rider's head. This sentence provides specific instructions on the proper positioning of a helmet, which is direct evidence that a helmet must fit correctly to be effective.","incorrect":["",{"choice":"The school choir rehearsed a song about the moon.","category":"irrelevant information","reason":"This information is not part of the passage provided and has nothing to do with bike safety or helmet usage."},{"choice":"The passage says every reader already knew about bike safety.","category":"misinterpretation of text","reason":"The passage does not state that readers already knew these safety tips; it describes a safety officer teaching them."},{"choice":"The title names the topic but gives no proof.","category":"missing evidence","reason":"The title is not mentioned in the passage, and even if it were, the specific description of how a helmet should fit is much stronger proof than a title would be."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":96,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0097","version":3,"contentHash":"sha256:dc0fcd56f9fb46a7526abad0035f1d5226cfbd70b9070fca4ba2ed2038f784a1","question":"Read the passage. Grade 4 foundation passage: Transportation planners added bus routes near busy neighborhoods. The new route stopped near the clinic, grocery store, and community center. Riders waited less time because buses arrived every fifteen minutes.\n\nWhich sentence from the passage best supports this idea: The new bus route served community needs.","choices":["A bakery sold cinnamon rolls before sunrise.","The new route stopped near the clinic, grocery store, and community center.","The passage says every reader already knew about city buses.","The title names the topic but gives no proof."],"correct":1,"studyAid":{"definition":"To find evidence that supports an idea, look for sentences that provide specific examples or facts that prove the idea is true.","example":"Idea: The park is a fun place. Supporting fact: The park has a large playground, a swimming pool, and a soccer field.","strategyClue":"Highlight the key words in the idea you are trying to support, such as 'community needs,' then scan the passage for sentences that list places or services where people gather.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: The new route stopped near the clinic, grocery store, and community center. This sentence identifies specific locations that provide essential services to the public, directly supporting the idea that the bus route serves 'community needs.'","incorrect":[{"choice":"A bakery sold cinnamon rolls before sunrise.","category":"irrelevant information","reason":"This sentence mentions a business but does not relate to the bus route or how it helps the community. It provides no evidence for the main idea."},"",{"choice":"The passage says every reader already knew about city buses.","category":"unsupported claim","reason":"This statement is not found in the text and does not explain how the bus route helps people in the neighborhood."},{"choice":"The title names the topic but gives no proof.","category":"incorrect evidence","reason":"This sentence comments on the passage's structure rather than providing a fact from the text that proves the bus route is helpful."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":97,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0098","version":3,"contentHash":"sha256:e9351d3be09a18ab3a953a7b9662cb620977fc8f0db14e2a7d1ae2e797366588","question":"Read the passage. Grade 4 foundation passage: Cast members prepared a play through teamwork. Actors practiced lines while stage crew members painted scenery and tested lights. When a curtain rope tangled, two students fixed it before rehearsal began.\n\nWhich detail is the strongest evidence for the answer, \"The production required more than acting.\"?","choices":["The passage says every reader already knew about school play.","A math poster showed different kinds of triangles.","Actors practiced lines while stage crew members painted scenery and tested lights.","The title names the topic but gives no proof."],"correct":2,"studyAid":{"definition":"Strong evidence is a specific detail from a text that directly supports a claim or answers a question.","example":"Claim: The garden is messy. Evidence: Weeds grew over the path and old tools were left in the grass.","strategyClue":"Look for a sentence that lists specific tasks performed by different people to show that many parts make up a whole project.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Actors practiced lines while stage crew members painted scenery and tested lights. This sentence shows that besides actors, other people like the stage crew were performing different essential tasks, which proves a production involves more than just acting.","incorrect":[{"choice":"The passage says every reader already knew about school play.","category":"irrelevant information","reason":"This statement describes the background knowledge of the audience, not the actual work required to put on the play itself."},{"choice":"A math poster showed different kinds of triangles.","category":"off-topic detail","reason":"This detail is completely unrelated to the production of a play and does not provide any evidence about what tasks are required."},"",{"choice":"The title names the topic but gives no proof.","category":"missing supporting evidence","reason":"A title might introduce a subject, but it does not describe the specific actions or people involved, so it cannot serve as evidence for what a production requires."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":98,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0099","version":3,"contentHash":"sha256:c79b1f8302591dc2dc4d49e9709cd559a88cbd0e11bdda342396303305a3c955","question":"Read the passage. Grade 4 foundation passage: Cafeteria workers turned food scraps into compost. Fruit peels and vegetable ends went into a covered bin behind the cafeteria. After several weeks, the dark compost was mixed into flower beds.\n\nWhich sentence from the passage best supports this idea: Food scraps can become useful instead of being thrown away.","choices":["The title names the topic but gives no proof.","A new scoreboard was installed in the gym.","The passage says every reader already knew about compost bin.","After several weeks, the dark compost was mixed into flower beds."],"correct":3,"studyAid":{"definition":"To support an idea, find a sentence in the text that gives a specific example or fact that makes the main idea true.","example":"Idea: Dogs are helpful. Evidence: My dog alerts us when the doorbell rings.","strategyClue":"First, identify the main idea about 'useful food scraps.' Then, read each sentence and ask, 'Does this sentence show the scraps being used for something?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: After several weeks, the dark compost was mixed into flower beds. This sentence provides evidence that the food scraps were transformed into something beneficial for the school garden, directly supporting the idea that they can be used rather than thrown away.","incorrect":[{"choice":"The title names the topic but gives no proof.","category":"not a sentence","reason":"This is a statement about the text, not a sentence from the passage itself, and it does not provide any evidence about what happens to food scraps."},{"choice":"A new scoreboard was installed in the gym.","category":"irrelevant information","reason":"This sentence describes a change in the gym, but it has nothing to do with food scraps or composting."},{"choice":"The passage says every reader already knew about compost bin.","category":"not in text","reason":"This sentence is not present in the passage provided, and it does not explain how food scraps are recycled."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":99,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}},{"id":"reading-comprehension-text-evidence-q0100","version":3,"contentHash":"sha256:080aee629bbf85d6e7eee01076c4480676963520a3395acb9c7e1ffd3a211ccb","question":"Read the passage. Grade 4 foundation passage: Science students tracked local weather patterns. They measured rainfall, wind direction, temperature, and cloud cover every day. Their chart showed that cool mornings often followed clear nights.\n\nWhich detail is the strongest evidence for the answer, \"The students gathered more than one kind of weather evidence.\"?","choices":["They measured rainfall, wind direction, temperature, and cloud cover every day.","The music teacher tuned a violin before class.","The passage says every reader already knew about weather station.","The title names the topic but gives no proof."],"correct":0,"studyAid":{"definition":"To find evidence for a claim, look for the specific sentence in the text that lists facts, data, or examples proving that the claim is true.","example":"Claim: The classroom had many supplies. Evidence: The desks were filled with paper, pencils, markers, and glue.","strategyClue":"Scan the text for a sentence that acts like a list of multiple items. Matching the specific items in the sentence to the keywords in the question will help you find the strongest proof.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: They measured rainfall, wind direction, temperature, and cloud cover every day. This sentence lists four distinct types of data the students collected, which directly supports the idea that they gathered multiple kinds of weather evidence.","incorrect":["",{"choice":"The music teacher tuned a violin before class.","category":"irrelevant information","reason":"This sentence describes a music class and has no connection to weather patterns or the scientific work performed by the students."},{"choice":"The passage says every reader already knew about weather station.","category":"unsupported claim","reason":"The passage does not state that readers already know about weather stations, and even if it did, this does not serve as evidence for how many kinds of evidence the students collected."},{"choice":"The title names the topic but gives no proof.","category":"lacks supporting evidence","reason":"While a title might name a subject, it does not provide the specific details or measurements needed to prove that multiple types of evidence were gathered."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["text evidence","explicit details","supporting answers"],"standards":["RI/RL.2-6.1"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-text-evidence","sequence":100,"skillIds":["reading-comprehension.comprehension"],"standardIds":["RI/RL.2-6.1","RI/RL.2-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-text-evidence"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-text-evidence"] = chunkSet;
  }
})();
